record.field:
partner = record.partner_id
if not partner.x_is_verified:   raise UserError("Customer is not a group.")
claimants = partner.x_claimants_ids
if not claimants:   raise UserError("No claimants found.")
new_moves = []
for claimant in claimants:
    new_move = record.copy({
        'partner_id': claimant.x_res_partner.id,
        'invoice_origin': record.name,
    })
    for line in new_move.invoice_line_ids:
        line.write({
            'price_unit': line.price_unit * claimant.x_share,
        })
    new_moves.append(new_move.id)
record.button_cancel()
action = {
    'type': 'ir.actions.act_window',
    'name': 'Split Invoices',
    'res_model': 'account.move',
    'view_mode': 'list',
    'domain': [('id', 'in', new_moves)],
}
